public interface IStationView {
    string Query { get; }
    void ShowTotal(double total);
    event EventHandler QueryChanged;                 // view forwards gestures
}
public sealed class StationPresenter {
    private readonly IStationView view; private readonly StationModel model;
    public StationPresenter(IStationView v, StationModel m) {
        view = v; model = m; view.QueryChanged += (_, __) => Refresh();
    }
    public void Refresh() => view.ShowTotal(model.Total(view.Query));
}

public sealed class StationModel : INotifyPropertyChanged {
    public event PropertyChangedEventHandler PropertyChanged;
    public double Total { get => total;
        private set { total = value; PropertyChanged?.Invoke(this, new("Total")); } }
}
var source = new BindingSource { DataSource = model };
totalLabel.DataBindings.Add("Text", source, nameof(StationModel.Total));
